(async () => {
  try {
    const tc = window.TuquetCrawler;
    const startTime = Date.now();
    const rawHtml = document.documentElement.outerHTML;
    const crawl = await tc.crawlDocument(document, {
      autoDismissModals: true,
      autoScroll: false,
      extractMetadata: true,
      extractMainContent: true,
      toMarkdown: true
    });
    const markdown = crawl.markdown || '';
    const tokenSavings = tc.estimateTokenSavings(rawHtml, markdown);
    automaNextBlock({
      success: true,
      domain: 'en.wikipedia.org',
      url: window.location.href,
      pageType: crawl.pageType,
      title: crawl.metadata?.title || document.title,
      description: crawl.metadata?.description,
      wordCount: crawl.article?.wordCount,
      readingTimeMinutes: crawl.article?.readingTimeMinutes,
      articleConfidence: crawl.article?.confidenceScore,
      rawLength: rawHtml.length,
      markdownLength: markdown.length,
      tokenSavings: tokenSavings,
      markdownSample: markdown.slice(0, 800),
      executionMs: Date.now() - startTime
    });
  } catch (err) {
    automaNextBlock({ $error: true, message: err.message });
  }
})();
